pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner) public {
        // Only test when msg.sender is the owner
        address ownerBefore = c.owner();
        vm.assume(msg.sender == ownerBefore);

        // Record owner before calling owned()
        address ownerBeforeCall = c.owner();

        // Call owned() - this is the function that triggers the difference
        c.owned();

        // Assert: after owned() is called, the owner must not have changed to address(0)
        // unless it was already address(0) before the call
        address actualOwner = c.owner();
        assertTrue(actualOwner == ownerBeforeCall || actualOwner != address(0));
    }
}

