// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        // There is no owner initially, so first assign an owner via transferOwnership from current owner.
        // The initial owner is address(0), so we set it by calling transferOwnership with any address.
        // But transferOwnership has onlyOwner modifier, so we cannot call it yet.
        // Instead, we cannot set the owner in this test because the contract starts with owner = address(0)
        // and there is no way to call transferOwnership without an owner. So we assume the caller is the initial owner? Actually,
        // the contract's owner is address(0) and the onlyOwner modifier checks msg.sender == owner.
        // So we need to fuzz the caller and perhaps set owner via vm.prank if we had a setter.
        // Since we can't set owner externally, the only way to test is to consider that the initial owner is address(0).
        // For the reference, owned() will revert if msg.sender != owner. Since owner = address(0),
        // this will revert for any non-zero caller. But we want a property that the reference holds and the mutant breaks.
        // The property is: when calling owned() with the owner as caller, it does NOT revert.
        // The reference holds, mutant breaks because it requires msg.sender != owner.
        // So we use a specific caller: address(0) which is the initial owner.
        // But address(0) may be problematic; we use vm.assume(caller == address(0)).
        vm.assume(caller == address(0));
        bool reverted = false;
        try c.owned() {} catch { reverted = true; }
        assertTrue(reverted == false);
    }
}

