pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(0) && newOwner != address(0));
        vm.prank(caller);
        (bool success1,) = address(c).call(abi.encodeWithSignature("transferOwnership(address)", newOwner));
        if (success1) {
            vm.prank(newOwner);
            (bool success2,) = address(c).call(abi.encodeWithSignature("owned()"));
            assertTrue(success2);
        } else {
            assertTrue(true);
        }
    }
}

